#!/bin/sh
set -e

cat <<EOSQL | psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB"
CREATE USER ${ICINGAWEB_USER} WITH PASSWORD '${ICINGAWEB_PASSWORD}';
CREATE DATABASE ${ICINGAWEB_DB} WITH OWNER ${ICINGAWEB_USER};
GRANT ALL PRIVILEGES ON DATABASE ${ICINGAWEB_DB} TO ${ICINGAWEB_USER};
\c ${ICINGAWEB_DB} ${POSTGRES_USER}
GRANT ALL ON SCHEMA public TO ${ICINGAWEB_USER};
EOSQL
